CREATE OR REPLACE FUNCTION public.can_submit(_pid uuid, _note text DEFAULT NULL::text, _ack_failed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.promotions; s public.submissions; _reasons text[] := '{}'; _role public.org_role; _settings public.org_settings;
  _last_decided uuid; _open int;
begin
  select * into p from public.promotions where id = _pid;
  if p.id is null or not public.can_read_promotion(_pid) then return jsonb_build_object('ok', false, 'reasons', jsonb_build_array('not_found')); end if;
  if p.org_id is null then return jsonb_build_object('ok', false, 'reasons', jsonb_build_array('personal_promotion')); end if;
  _role := public.org_role_of(p.org_id, auth.uid());
  if _role = 'viewer' or not (p.owner_id = auth.uid() or _role in ('owner', 'admin', 'creator')) then _reasons := array_append(_reasons, ('forbidden')::text); end if;
  if p.review_status not in ('draft', 'changes_requested', 'rejected', 'conditionally_approved') then _reasons := array_append(_reasons, ('invalid_status')::text); end if;
  select * into s from public.submissions where id = p.current_version_id;
  if s.id is null then _reasons := array_append(_reasons, ('no_version')::text);
  elsif s.status = 'failed' and not _ack_failed then _reasons := array_append(_reasons, ('analysis_failed')::text);
  elsif s.status not in ('done', 'failed') then _reasons := array_append(_reasons, ('analysis_not_done')::text);
  end if;
  select * into _settings from public.org_settings where org_id = p.org_id;
  if s.id is not null and coalesce(_settings.require_uploader_responses, true) then
    select count(*) into _open from public.findings f
    where f.run_id = public.latest_run_id(s.id) and f.status not in ('resolved')
      and not exists (select 1 from public.finding_responses r where r.finding_id = f.id and r.actor_role = 'uploader');
    if _open > 0 then _reasons := array_append(_reasons, (('missing_uploader_responses:' || _open))::text); end if;
  end if;
  select submission_id into _last_decided from public.review_decisions
  where promotion_id = _pid and decision in ('approve', 'conditional_approve', 'request_changes', 'reject') order by created_at desc limit 1;
  if _last_decided is not null and _last_decided = p.current_version_id then
    if p.review_status = 'changes_requested' then
      if coalesce(trim(_note), '') = '' then _reasons := array_append(_reasons, ('note_required_same_version')::text); end if;
    elsif p.review_status in ('rejected', 'conditionally_approved') then
      _reasons := array_append(_reasons, ('new_version_required')::text);
    end if;
  end if;
  return jsonb_build_object('ok', cardinality(_reasons) = 0, 'reasons', to_jsonb(_reasons));
end $function$;

CREATE OR REPLACE FUNCTION public.claim_add_from_finding(_finding uuid, _name text, _text_ar text, _substantiation jsonb, _approve boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f public.findings; p public.promotions; _role public.org_role; _id uuid; c public.claims;
begin
  select * into f from public.findings where id = _finding;
  if f.id is null or f.rule_code <> 'SYS-CLAIMS' or not public.can_read_submission(f.submission_id) then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  select p2.* into p from public.promotions p2 join public.submissions s on s.promotion_id = p2.id where s.id = f.submission_id;
  _role := public.lib_role(p.org_id);
  if _role is null or _role = 'legal' then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if jsonb_array_length(coalesce(_substantiation, '[]')) = 0 then raise exception 'code:substantiation_required' using errcode = 'P0001'; end if;
  insert into public.claims (org_id, name, text_ar, substantiation, status, source_finding_id, product_ids, communication_types)
  values (p.org_id, trim(_name), trim(_text_ar), _substantiation, 'pending_review', _finding,
          case when p.product_id is null then '{}' else array[p.product_id] end, array[p.communication_type::text])
  returning id into _id;
  insert into public.promotion_claims (promotion_id, claim_id, link_source, linked_by) values (p.id, _id, 'finding_fix', auth.uid())
  on conflict do nothing;
  if _approve then
    if _role not in ('owner', 'admin', 'reviewer', 'compliance_lead') then raise exception 'code:forbidden' using errcode = '42501'; end if;
    -- The reviewer adds and approves in one step; the claim records them as reviewer (they did not author the ad).
    update public.claims set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now(), created_by = null where id = _id returning * into c;
    perform public.resolve_claim_findings(c);
  end if;
  perform public.log_review_event(p.id, f.submission_id, 'claim_fix', null, null, jsonb_build_object('claim_id', _id, 'approved', _approve));
  return _id;
end $function$;

CREATE OR REPLACE FUNCTION public.complete_rereview(_pid uuid, _still_valid boolean, _next_review date, _comment text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.promotions; _role public.org_role; d public.review_decisions; _to public.promotion_review_status;
begin
  select * into p from public.promotions where id = _pid for update;
  if p.id is null or p.org_id is null then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  _role := public.org_role_of(p.org_id, auth.uid());
  if _role is null or _role not in ('owner', 'admin', 'reviewer', 'compliance_lead') then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if p.review_status <> 'due_for_rereview' then raise exception 'code:invalid_status' using errcode = 'P0001'; end if;
  if public.promotion_uploader(_pid) = auth.uid() then raise exception 'code:separation_of_duties' using errcode = '42501'; end if;
  if _still_valid and (_next_review is null or _next_review <= current_date) then raise exception 'code:next_review_required' using errcode = 'P0001'; end if;
  if not _still_valid and coalesce(trim(_comment), '') = '' then raise exception 'code:reason_required' using errcode = 'P0001'; end if;
  _to := case when _still_valid then 'approved'::public.promotion_review_status else 'changes_requested' end;
  if _still_valid then update public.promotions set next_review_at = _next_review where id = _pid; end if;
  d := public.write_decision(p, case when _still_valid then 'approve' else 'request_changes' end, _role::text, _to, '{}',
    case when _still_valid then null else _comment end, null, _comment);
  update public.promotions set review_status = _to, approved_at = case when _still_valid then now() else approved_at end, updated_at = now() where id = _pid;
  perform public.log_review_event(_pid, p.current_version_id, 'rereviewed', 'due_for_rereview', _to::text,
    jsonb_build_object('decision_id', d.id, 'still_valid', _still_valid, 'next_review_at', _next_review));
  perform public.notify_user(p.owner_id, 'review_decided', p.current_version_id,
    jsonb_build_object('promotion_id', _pid, 'title', p.title, 'decision', case when _still_valid then 'approve' else 'request_changes' end));
  return d.id;
end $function$;

CREATE OR REPLACE FUNCTION public.escalate_promotion(_pid uuid, _legal_user uuid, _question text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.promotions; _role public.org_role; d public.review_decisions;
begin
  select * into p from public.promotions where id = _pid for update;
  if p.id is null or p.org_id is null then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  _role := public.org_role_of(p.org_id, auth.uid());
  if _role is null or _role not in ('owner', 'admin', 'reviewer', 'compliance_lead') then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if p.review_status <> 'in_review' then raise exception 'code:invalid_status' using errcode = 'P0001'; end if;
  if public.promotion_uploader(_pid) = auth.uid() then raise exception 'code:separation_of_duties' using errcode = '42501'; end if;
  if public.flow_is_live(_pid) then raise exception 'code:multi_level_flow' using errcode = 'P0001'; end if;
  if public.org_role_of(p.org_id, _legal_user) is distinct from 'legal' then raise exception 'code:not_legal_member' using errcode = 'P0001'; end if;
  if coalesce(trim(_question), '') = '' then raise exception 'code:question_required' using errcode = 'P0001'; end if;
  d := public.write_decision(p, 'escalate', _role::text, 'escalated', '{}', null, null, _question);
  update public.promotions set review_status = 'escalated', escalated_to = _legal_user, updated_at = now() where id = _pid;
  perform public.log_review_event(_pid, p.current_version_id, 'escalated', 'in_review', 'escalated', jsonb_build_object('legal_user', _legal_user, 'decision_id', d.id));
  perform public.notify_user(_legal_user, 'review_escalated', p.current_version_id, jsonb_build_object('promotion_id', _pid, 'title', p.title));
  return d.id;
end $function$;

