AS $function$
declare p public.promotions; _role public.org_role;
begin
  select * into p from public.promotions where id = _pid for update;
  if p.id is null or p.org_id is null then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  _role := public.org_role_of(p.org_id, auth.uid());
  if _role is null or _role not in ('owner', 'admin', 'reviewer', 'compliance_lead') then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if p.review_status <> 'pending_review' then raise exception 'code:invalid_status' using errcode = 'P0001'; end if;
  if public.promotion_uploader(_pid) = auth.uid() then raise exception 'code:separation_of_duties' using errcode = '42501'; end if;
  update public.promotions set review_status = 'in_review', assigned_reviewer_id = coalesce(assigned_reviewer_id, auth.uid()), updated_at = now() where id = _pid;
  perform public.log_review_event(_pid, p.current_version_id, 'opened', 'pending_review', 'in_review', '{}'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.org_metrics(_org uuid, _from timestamp with time zone, _to timestamp with time zone, _filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.org_settings; _sla int; _wk int[]; f jsonb := coalesce(_filters, '{}'::jsonb); out jsonb;
begin
  if not public.is_org_member(_org, array['owner', 'admin', 'reviewer', 'compliance_lead', 'viewer']::public.org_role[]) then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if not public.org_feature(_org, 'analytics') then raise exception 'code:feature_off' using errcode = 'P0001'; end if;
  if _from is null or _to is null or _to < _from then raise exception 'code:invalid_date' using errcode = 'P0001'; end if;
  select * into s from public.org_settings where org_id = _org;
  _sla := coalesce(s.review_sla_business_days, 3);
  _wk := coalesce(s.weekend_days, '{5,6}');

  with p as (
    select pr.* from public.promotions pr
    where pr.org_id = _org and not pr.is_demo
      and (f->>'product_id' is null or pr.product_id = (f->>'product_id')::uuid)
      and (f->>'channel' is null or (f->>'channel') = any(pr.channels))
      and (f->>'communication_type' is null or pr.communication_type::text = f->>'communication_type')
      and (f->>'uploader' is null or pr.owner_id = (f->>'uploader')::uuid)
      and (f->>'reviewer' is null or pr.assigned_reviewer_id = (f->>'reviewer')::uuid)
      and (f->'tags' is null or pr.tags && array(select jsonb_array_elements_text(f->'tags')))
  ),
  sub as (select e.* from public.review_events e join p on p.id = e.promotion_id where e.event_type = 'submitted'),
  sub_r as (select * from sub where created_at >= _from and created_at < _to),
  dec as (select d.* from public.review_decisions d join p on p.id = d.promotion_id
          where d.decision in ('approve', 'conditional_approve', 'request_changes', 'reject')),
  dec_r as (select * from dec where created_at >= _from and created_at < _to),
  first_sub as (select promotion_id, min(created_at) at from sub group by promotion_id),
  first_dec as (select distinct on (promotion_id) promotion_id, decision, created_at from dec order by promotion_id, created_at, id),
  first_appr as (select promotion_id, min(created_at) at from dec where decision = 'approve' group by promotion_id),
  -- SLA: each decision against the latest submission before it.
  dec_sla as (
    select d.id, public.business_days_between(
      (select max(x.created_at) from sub x where x.promotion_id = d.promotion_id and x.created_at <= d.created_at), d.created_at, _wk) <= _sla ok
    from dec_r d),
  appr_time as (
    select extract(epoch from (a.at - fs.at)) / 3600.0 h from first_appr a join first_sub fs using (promotion_id)
    where a.at >= _from and a.at < _to),
  first_resp as (
    select extract(epoch from (r.at - fs.at)) / 3600.0 h from first_sub fs
    cross join lateral (
      select min(t) at from (
        select min(fr.created_at) t from public.finding_responses fr join public.submissions sb on sb.id = fr.submission_id
          where sb.promotion_id = fs.promotion_id and fr.actor_role = 'reviewer' and fr.created_at >= fs.at
        union all select min(c.created_at) from public.comments c join p on p.id = c.promotion_id
          where c.promotion_id = fs.promotion_id and c.author_id <> p.owner_id and c.created_at >= fs.at
        union all select min(d.created_at) from dec d where d.promotion_id = fs.promotion_id and d.created_at >= fs.at) z) r
    where fs.at >= _from and fs.at < _to and r.at is not null),
  iters as (
    select (select count(*) from sub x where x.promotion_id = a.promotion_id and x.created_at <= a.at) - 1 n
    from first_appr a where a.at >= _from and a.at < _to)
  select jsonb_build_object(
    'range', jsonb_build_object('from', _from, 'to', _to, 'sla_business_days', _sla),
    'promotions_submitted', (select count(distinct promotion_id) from sub_r),
    'versions_submitted', (select count(*) from sub_r),
    'avg_versions', (select case when count(distinct promotion_id) = 0 then 0 else greatest(1.0, round(count(*)::numeric / count(distinct promotion_id), 2)) end from sub_r),
    'early_requests', (select case when count(*) = 0 then 0 else round(count(*) filter (where p.deadline_at is not null
        and public.business_days_between(x.created_at, p.deadline_at, _wk) < _sla)::numeric / count(*), 4) end
      from sub_r x join p on p.id = x.promotion_id),
    'sla_compliance', (select case when count(*) = 0 then 0 else round(count(*) filter (where ok)::numeric / count(*), 4) end from dec_sla),
    'reviews_decided', (select count(*) from dec_r),
    'first_time_approval', (select case when count(*) = 0 then 0 else round(count(*) filter (where fd.decision = 'approve')::numeric / count(*), 4) end
      from first_dec fd join p on p.id = fd.promotion_id where p.created_at >= _from and p.created_at < _to),
    'approval_time_hours', (select jsonb_build_object('mean', round(avg(h)::numeric, 2), 'median', round((percentile_cont(0.5) within group (order by h))::numeric, 2), 'n', count(*)) from appr_time),
    'first_response_hours', (select jsonb_build_object('mean', round(avg(h)::numeric, 2), 'median', round((percentile_cont(0.5) within group (order by h))::numeric, 2), 'n', count(*)) from first_resp),
    'iterations', (select jsonb_build_object('mean', round(avg(n)::numeric, 2), 'median', round((percentile_cont(0.5) within group (order by n))::numeric, 2), 'n', count(*)) from iters),
    'reasons', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'label_ar', r.label_ar, 'label_en', r.label_en, 'count', c.n) order by c.n desc)
      from (select unnest(d.reason_ids) rid, count(*) n from dec_r d where d.decision in ('reject', 'request_changes') group by 1) c
      join public.rejection_reasons r on r.id = c.rid), '[]'::jsonb),
    'reasons_other', (select count(*) from dec_r where decision in ('reject', 'request_changes') and reason_other is not null),
    'workload', coalesce((select jsonb_agg(w order by w->>'user_id') from (
      select jsonb_build_object('user_id', u, 'name', (select coalesce(m.display_name, m.email) from public.org_members m where m.org_id = _org and m.user_id = u),
        'decisions', (select count(*) from dec_r d where d.actor_id = u),
        'open', (select count(*) from p where p.assigned_reviewer_id = u and p.review_status in ('pending_review', 'in_review'))) w
      from (select actor_id u from dec_r union select assigned_reviewer_id from p where assigned_reviewer_id is not null and review_status in ('pending_review', 'in_review')) us) ww), '[]'::jsonb),
    'volume', jsonb_build_object(
      'by_status', coalesce((select jsonb_object_agg(review_status, n) from (select review_status, count(*) n from p where created_at >= _from and created_at < _to group by 1) v), '{}'::jsonb),
      'by_channel', coalesce((select jsonb_object_agg(ch, n) from (select unnest(channels) ch, count(*) n from p where created_at >= _from and created_at < _to group by 1) v), '{}'::jsonb),
      'by_type', coalesce((select jsonb_object_agg(communication_type, n) from (select communication_type, count(*) n from p where created_at >= _from and created_at < _to group by 1) v), '{}'::jsonb),
      'by_product', coalesce((select jsonb_object_agg(coalesce(pr.name_ar, '—'), n) from (select product_id, count(*) n from p where created_at >= _from and created_at < _to group by 1) v
                               left join public.products pr on pr.id = v.product_id), '{}'::jsonb)),
    'risk_accepted', (select count(*) from public.review_decisions d join p on p.id = d.promotion_id where d.decision = 'risk_accept' and d.created_at >= _from and d.created_at < _to)
  ) into out;
  return out;
end $function$;

CREATE OR REPLACE FUNCTION public.resolve_comment(_id uuid, _resolved boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.comments; p public.promotions;
begin
  select * into c from public.comments where id = _id;
  select * into p from public.promotions where id = c.promotion_id;
  if c.id is null or c.deleted_at is not null then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  if not (p.owner_id = auth.uid() or (p.org_id is not null and public.is_org_member(p.org_id, array['owner', 'admin', 'reviewer', 'compliance_lead']::public.org_role[]))) then
    raise exception 'code:forbidden' using errcode = '42501';
  end if;
  update public.comments set resolved_at = case when _resolved then now() end, resolved_by = case when _resolved then auth.uid() end
  where id = _id or carried_from_comment_id = _id or id = c.carried_from_comment_id;
end $function$;

CREATE OR REPLACE FUNCTION public.respond_finding(_finding uuid, _action text, _comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  f public.findings; s public.submissions; p public.promotions; _role public.org_role; _actor text; _id uuid;
  _uploader_actions constant text[] := array['agree_will_action', 'dispute'];
  _reviewer_actions constant text[] := array['agree_please_action', 'not_required', 'dismiss'];
begin
  select * into f from public.findings where id = _finding;
  if f.id is null or not public.can_read_submission(f.submission_id) then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  select * into s from public.submissions where id = f.submission_id;
  select * into p from public.promotions where id = s.promotion_id;
  if p.id is null or s.is_demo then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if f.run_id <> public.latest_run_id(s.id) then raise exception 'code:finding_superseded' using errcode = 'P0001'; end if;
  _role := case when p.org_id is null then null else public.org_role_of(p.org_id, auth.uid()) end;

  if _action = any(_uploader_actions) or (_action = 'reply' and (p.owner_id = auth.uid() or s.user_id = auth.uid() or _role in ('creator'))) then
    -- Uploader side: the promotion owner, the uploader of the version, or an org uploader role.
    if not (p.owner_id = auth.uid() or s.user_id = auth.uid() or _role in ('owner', 'admin', 'creator')) then
      raise exception 'code:forbidden' using errcode = '42501';
    end if;
    if p.review_status not in ('draft', 'changes_requested', 'rejected', 'conditionally_approved', 'pending_review') then
      raise exception 'code:invalid_status' using errcode = 'P0001';
    end if;
    _actor := 'uploader';
  elsif _action = any(_reviewer_actions) or _action = 'reply' then
    -- Reviewer side: org reviewers, never on a version they uploaded (separation of duties).
    if _role is null or _role not in ('owner', 'admin', 'reviewer', 'compliance_lead') then raise exception 'code:forbidden' using errcode = '42501'; end if;
    if s.user_id = auth.uid() then raise exception 'code:separation_of_duties' using errcode = '42501'; end if;
    if p.review_status not in ('in_review', 'escalated') then raise exception 'code:invalid_status' using errcode = 'P0001'; end if;
    _actor := 'reviewer';
  else
    raise exception 'code:invalid_action' using errcode = 'P0001';
  end if;
  if _action in ('dispute', 'not_required', 'dismiss') and coalesce(trim(_comment), '') = '' then
    raise exception 'code:comment_required' using errcode = 'P0001';
  end if;

  insert into public.finding_responses (finding_id, submission_id, actor_id, actor_role, action, comment)
  values (f.id, f.submission_id, auth.uid(), _actor, _action, nullif(trim(coalesce(_comment, '')), ''))
  returning id into _id;

  -- Status sync: a reviewer response always overrides an uploader response.
  if public.response_status(_action) is not null and (
       _actor = 'reviewer'
       or not exists (select 1 from public.finding_responses r where r.finding_id = f.id and r.actor_role = 'reviewer')) then
    update public.findings set status = public.response_status(_action) where id = f.id;
  end if;
  return _id;
end $function$;

CREATE OR REPLACE FUNCTION public.review_claim(_id uuid, _decision text, _reason_ids uuid[] DEFAULT '{}'::uuid[], _comment text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.claims; _role public.org_role;
begin
  select * into c from public.claims where id = _id for update;
  if c.id is null then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  _role := public.lib_role(c.org_id);
  if _role is null or _role not in ('owner', 'admin', 'reviewer', 'compliance_lead') then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if c.created_by = auth.uid() then raise exception 'code:separation_of_duties' using errcode = '42501'; end if;
  if c.status <> 'pending_review' then raise exception 'code:invalid_status' using errcode = 'P0001'; end if;
  if _decision not in ('approve', 'reject', 'request_changes') then raise exception 'code:invalid_decision' using errcode = 'P0001'; end if;
  if _decision <> 'approve' and cardinality(coalesce(_reason_ids, '{}')) = 0 and coalesce(trim(_comment), '') = '' then
    raise exception 'code:reason_required' using errcode = 'P0001';
  end if;
  update public.claims set status = case _decision when 'approve' then 'approved' when 'reject' then 'rejected' else 'changes_requested' end,
    reviewed_by = auth.uid(), reviewed_at = now(), review_reason_ids = coalesce(_reason_ids, '{}'), review_comment = nullif(trim(coalesce(_comment, '')), '')
  where id = _id returning * into c;
  if _decision = 'approve' then
    update public.claims set status = 'archived' where id = c.supersedes_id and status = 'approved';
    perform public.resolve_claim_findings(c);
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.save_approval_preset(_org uuid, _id uuid, _name text, _mode text, _is_default boolean, _steps jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare _pid uuid := _id; x jsonb; _i integer := 0; _users uuid[];
begin
  if not public.is_org_member(_org, array['owner', 'admin']::public.org_role[]) then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if _mode not in ('sequential', 'parallel') then raise exception 'code:invalid_mode' using errcode = 'P0001'; end if;
  if jsonb_typeof(_steps) <> 'array' or jsonb_array_length(_steps) not between 1 and 10 then raise exception 'code:steps_required' using errcode = 'P0001'; end if;
  if coalesce(trim(_name), '') = '' then raise exception 'code:name_required' using errcode = 'P0001'; end if;
  if _is_default then update public.approval_presets set is_default = false where org_id = _org and id is distinct from _pid; end if;
  if _pid is null then
    insert into public.approval_presets (org_id, name, mode, is_default, created_by) values (_org, trim(_name), _mode, _is_default, auth.uid()) returning id into _pid;
  else
    update public.approval_presets set name = trim(_name), mode = _mode, is_default = _is_default, version = version + 1, updated_at = now()
    where id = _pid and org_id = _org;
    if not found then raise exception 'code:not_found' using errcode = 'P0001'; end if;
    delete from public.approval_preset_steps where preset_id = _pid;
  end if;
  for x in select * from jsonb_array_elements(_steps) loop
    _i := _i + 1;
    _users := coalesce((select array_agg(v::uuid) from jsonb_array_elements_text(coalesce(x->'user_ids', '[]'::jsonb)) v), '{}');
    if exists (select 1 from unnest(_users) u where public.org_role_of(_org, u) is null or public.org_role_of(_org, u) not in ('owner', 'admin', 'reviewer', 'compliance_lead')) then
      raise exception 'code:not_a_reviewer' using errcode = 'P0001';
    end if;
    if nullif(x->>'role', '') is not null and (x->>'role') not in ('owner', 'admin', 'reviewer', 'compliance_lead') then raise exception 'code:invalid_role' using errcode = 'P0001'; end if;
    insert into public.approval_preset_steps (preset_id, position, role, user_ids, label_ar)
    values (_pid, _i, nullif(x->>'role', '')::public.org_role, _users, coalesce(nullif(trim(x->>'label_ar'), ''), 'المرحلة ' || _i));
  end loop;
  insert into public.audit_events (actor, action, target_table, target_id, meta)
  values (auth.uid(), 'approval_preset.save', 'approval_presets', _pid::text, jsonb_build_object('org_id', _org, 'mode', _mode, 'steps', _steps));
  return _pid;
end $function$;

CREATE OR REPLACE FUNCTION public.set_org_rule_pack(_org uuid, _pack text, _enabled boolean, _include_drafts boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_org_member(_org, array['owner', 'admin', 'compliance_lead']::public.org_role[]) then
    raise exception 'code:forbidden' using errcode = '42501';
  end if;
  if exists (select 1 from public.rule_packs where code = _pack and always_enabled) and not _enabled then
    raise exception 'code:pack_always_enabled' using errcode = 'P0001';
  end if;
  insert into public.org_rule_packs (org_id, pack_code, enabled, include_draft_rules, updated_by, updated_at)
  values (_org, _pack, _enabled, _include_drafts, auth.uid(), now())
  on conflict (org_id, pack_code) do update
    set enabled = excluded.enabled, include_draft_rules = excluded.include_draft_rules,
        updated_by = excluded.updated_by, updated_at = now();
end $function$;

CREATE OR REPLACE FUNCTION public.set_risk_acceptor(_org uuid, _user uuid, _on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_org_member(_org, array['owner', 'admin']::public.org_role[]) then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if public.org_role_of(_org, _user) is null or public.org_role_of(_org, _user) not in ('owner', 'admin', 'reviewer', 'compliance_lead', 'legal') then
    raise exception 'code:not_a_reviewer' using errcode = 'P0001';
  end if;
  update public.org_members set can_accept_risk = coalesce(_on, false) where org_id = _org and user_id = _user;
  insert into public.audit_events (actor, action, target_table, target_id, meta)
  values (auth.uid(), 'risk_acceptor', 'org_members', _user::text, jsonb_build_object('org_id', _org, 'on', coalesce(_on, false)));
end $function$;

CREATE OR REPLACE FUNCTION public.set_rule_override(_org uuid, _rule_code text, _patch jsonb, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare _id uuid; k text;
begin
  if public.lib_role(_org) is null or public.lib_role(_org) not in ('owner', 'admin', 'compliance_lead') then raise exception 'code:forbidden' using errcode = '42501'; end if;
  if coalesce(trim(_reason), '') = '' or char_length(trim(_reason)) < 3 then raise exception 'code:reason_required' using errcode = 'P0001'; end if;
  for k in select jsonb_object_keys(coalesce(_patch, '{}'::jsonb)) loop
    if k not in ('exclude_channels', 'exclude_product_types', 'exclude_communication_types', 'exclude_audiences', 'disabled') then
      raise exception 'code:invalid_override' using errcode = 'P0001';
    end if;
  end loop;
  if _rule_code like 'SYS-%' then raise exception 'code:invalid_override' using errcode = 'P0001'; end if;
  update public.org_rule_overrides set archived_at = now() where org_id = _org and rule_code = _rule_code and archived_at is null;
  insert into public.org_rule_overrides (org_id, rule_code, applicability_patch, reason) values (_org, _rule_code, _patch, trim(_reason)) returning id into _id;
  insert into public.audit_events (actor, action, target_table, target_id, meta)
  values (auth.uid(), 'rule_override', 'org_rule_overrides', _id::text, jsonb_build_object('org_id', _org, 'rule_code', _rule_code, 'patch', _patch, 'reason', _reason));
  return _id;
end $function$;

CREATE OR REPLACE FUNCTION public.submit_claim(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.claims;
begin
  select * into c from public.claims where id = _id for update;
  if c.id is null or public.lib_role(c.org_id) is null then raise exception 'code:not_found' using errcode = 'P0001'; end if;
  if c.status not in ('draft', 'changes_requested', 'rejected') then raise exception 'code:invalid_status' using errcode = 'P0001'; end if;
  if jsonb_array_length(c.substantiation) = 0 then raise exception 'code:substantiation_required' using errcode = 'P0001'; end if;
  update public.claims set status = 'pending_review' where id = _id;
  perform public.notify_org(c.org_id, array['owner', 'admin', 'reviewer', 'compliance_lead']::public.org_role[], 'review_submitted', null,
    jsonb_build_object('claim_id', _id, 'title', c.name));
end $function$;

CREATE OR REPLACE FUNCTION public.submit_promotion_carry(_pid uuid, _note text DEFAULT NULL::text, _ack_failed boolean DEFAULT false, _carry integer[] DEFAULT '{}'::integer[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.promotions; _check jsonb; _from public.promotion_review_status;
begin
  select * into p from public.promotions where id = _pid for update;
  _check := public.can_submit(_pid, _note, _ack_failed);
  if not (_check->>'ok')::boolean then
    raise exception 'code:%', split_part(_check->'reasons'->>0, ':', 1) using errcode = 'P0001', detail = _check::text;
  end if;
  _from := p.review_status;
  update public.promotions set review_status = 'pending_review', submitted_at = coalesce(submitted_at, now()), updated_at = now() where id = _pid;
  perform public.log_review_event(_pid, p.current_version_id, 'submitted', _from::text, 'pending_review',
    jsonb_build_object('note', nullif(trim(coalesce(_note, '')), ''), 'analysis_failed_acknowledged', _ack_failed));
  if public.start_review_flow(_pid, _carry) is null then
    perform public.notify_org(p.org_id, array['owner', 'admin', 'reviewer', 'compliance_lead']::public.org_role[], 'review_submitted', p.current_version_id,
      jsonb_build_object('promotion_id', _pid, 'title', p.title));
  end if;
end $function$;

drop policy if exists "approval_preset_steps_select" on public.approval_preset_steps;
create policy "approval_preset_steps_select" on public.approval_preset_steps for SELECT to authenticated
  using ((EXISTS ( SELECT 1
   FROM approval_presets p
  WHERE ((p.id = approval_preset_steps.preset_id) AND is_org_member(p.org_id, ARRAY['owner'::org_role, 'admin'::org_role, 'reviewer'::org_role, 'compliance_lead'::org_role, 'creator'::org_role, 'legal'::org_role])))));

drop policy if exists "approval_presets_select" on public.approval_presets;
create policy "approval_presets_select" on public.approval_presets for SELECT to authenticated
  using (is_org_member(org_id, ARRAY['owner'::org_role, 'admin'::org_role, 'reviewer'::org_role, 'compliance_lead'::org_role, 'creator'::org_role, 'legal'::org_role]));

drop policy if exists "internal_rules_read" on public.internal_rules;
create policy "internal_rules_read" on public.internal_rules for SELECT to authenticated
  using (is_org_member(org_id, ARRAY['owner'::org_role, 'admin'::org_role, 'reviewer'::org_role, 'compliance_lead'::org_role, 'viewer'::org_role, 'creator'::org_role, 'legal'::org_role]));

drop policy if exists "preset_auto_apply_select" on public.preset_auto_apply;
create policy "preset_auto_apply_select" on public.preset_auto_apply for SELECT to authenticated
  using (is_org_member(org_id, ARRAY['owner'::org_role, 'admin'::org_role, 'reviewer'::org_role, 'compliance_lead'::org_role, 'creator'::org_role, 'legal'::org_role]));

drop policy if exists "org read submissions" on public.submissions;
create policy "org read submissions" on public.submissions for SELECT to authenticated
  using (((org_id IS NOT NULL) AND is_org_member(org_id, ARRAY['owner'::org_role, 'admin'::org_role, 'reviewer'::org_role, 'compliance_lead'::org_role, 'viewer'::org_role, 'legal'::org_role])));

drop policy if exists "evidence write" on storage.objects;
create policy "evidence write" on storage.objects for INSERT to authenticated
  with check (((bucket_id = 'evidence'::text) AND is_org_member(((storage.foldername(name))[1])::uuid, ARRAY['owner'::org_role, 'admin'::org_role, 'reviewer'::org_role, 'compliance_lead'::org_role, 'creator'::org_role])));

drop policy if exists "org media read" on storage.objects;
create policy "org media read" on storage.objects for SELECT to authenticated
  using (((bucket_id = 'media'::text) AND (EXISTS ( SELECT 1
   FROM submissions s
  WHERE (((s.id)::text = (storage.foldername(objects.name))[2]) AND (s.org_id IS NOT NULL) AND is_org_member(s.org_id, ARRAY['owner'::org_role, 'admin'::org_role, 'reviewer'::org_role, 'compliance_lead'::org_role, 'viewer'::org_role]))))));
